const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sections=[['welcome','Welcome'],['doctrine','Doctrine'],['scripture','Scripture'],['catechism','Catechism'],['rites','Rites & Liturgy'],['calendar','Calendar'],['symbols','Symbols'],['house','The House'],['membership','Membership']];
const original='<span class="badge">Original · supplied transcript</span>',expansion='<span class="badge expansion">New expansion · this edition</span>';
const bell=(x,y,s=1)=>`<g transform="translate(${x} ${y}) scale(${s})"><path d="M-18 18Q-12 10-12-5Q-12-22 0-22Q12-22 12-5Q12 10 18 18Z" fill="#b99b58" stroke="#e0c98c" stroke-width="1.4"/><ellipse cy="18" rx="18" ry="4" fill="#84642d" stroke="#e0c98c"/><circle cy="23" r="4" fill="#d6bb76"/><circle cy="-25" r="4" fill="none" stroke="#d6bb76"/></g>`;
const stocking='<g transform="scale(-1 1)"><path d="M-39-58H29V20Q64 10 73 35Q83 62 49 76L-13 97Q-50 107-56 78Q-60 60-39 45Z" fill="#8b3436" stroke="#d6bb76" stroke-width="2"/><path d="M-44-65H35V-37H-44Z" fill="#e9dec1" stroke="#d6bb76" stroke-width="2"/><path d="M-21-30V40Q-48 63-32 82" fill="none" stroke="#b7564f" stroke-width="2"/><path d="M-6 9L0 0L6 9L0 19Z" fill="#d6bb76"/></g>';
function seal(){return `<img class="house-emblem" src="assets/hohoho-emblem-round.svg" width="240" height="240" alt="HoHoHo seal: stocking, three bells, evergreen branches and winter star">`}
function illumination(){return `<img class="sacred-art hero-emblem" src="assets/hohoho-icon-left.png" width="1254" height="1254" alt="HoHoHo emblem: a left-facing crimson stocking beneath three golden bells, framed by evergreen branches and a winter star">`}
const head=(id,title,desc)=>`<div class="page-head"><div class="breadcrumb"><a href="#welcome">THE HOUSE</a> / ${sections.find(x=>x[0]===id)[1].toUpperCase()}</div><span class="eyebrow">The Canon of HoHoHo</span><h1>${title}</h1><p>${desc}</p></div>`;
const block=(title,text,badge=original)=>`<article class="panel">${badge}<h3>${title}</h3><p>${text}</p></article>`;
const quote=t=>`<blockquote>${esc(t)}</blockquote>`;
function welcome(){return `<section class="hero"><div class="hero-copy"><span class="eyebrow">A house of gifts, joy & wonder</span><h1>Keep the Ho.<br>Keep the <em>Hearth.</em></h1><p>Welcome to the Holy House of Horace. A fellowship of open hearts, freely given gifts, and the child who never quite forgot.</p><div class="actions"><a class="btn" href="#scripture">Open the Book of Ho &nbsp; ↗</a><a class="btn light" href="#doctrine">Discover the Three Ho’s</a></div><div class="hero-note">EST. IN WONDER &nbsp; · &nbsp; HELD IN GOOD HUMOUR</div></div><div class="manuscript">${illumination()}</div></section><div class="motto"><span>✦</span> “He that keepeth the Ho keepeth the Hearth.” <span>✦</span></div><section class="wrap"><div class="section-heading"><div><span class="eyebrow">The foundations of the House</span><h2>Three Ho’s. One calling.</h2></div><p>To give more than we take, to mend what we break, and to keep wonder alive in a weary world.</p></div><div class="three">${[['I','Gifts freely given','The world is healed through generosity. A gift is time, talent, kindness—or a toy.'],['II','Child and Santa','Every soul needs care. Every soul has something to give.'],['III','Joy as a sacred duty','Make room for rest, play, and the small light that lifts another heart.']].map(x=>`<article class="pillar"><span class="number">${x[0]} · THE ${x[0]==='I'?'FIRST':x[0]==='II'?'SECOND':'THIRD'} HO</span><h3>${x[1]}</h3><p>${x[2]}</p><a class="textlink" href="#doctrine">Read the doctrine ↗</a></article>`).join('')}</div><div class="feature"><div class="feature-art">${seal()}</div><div class="feature-copy"><span class="eyebrow">The living canon</span><h2>An old voice.<br>A very merry revelation.</h2><p>Read the 32 verses of the Book of Ho, the Psalm of the Sleigh-bells, and a catechism of 21 questions. Explore the rites, seasons, and symbols of an imagined winter order.</p><a href="#catechism" class="textlink">Begin with a question ↗</a></div></div></section><section class="wrap" style="padding-top:0"><div class="two">${block('A note to the reader','HoHoHo is a fictional, satirical religious worldbuilding project. Its medieval solemnity and Santa theology are part of the fiction. Participation here is imaginative and symbolic.','<span class="badge expansion">Editorial note</span>')}${block('Reading this edition','“Original” means text or a practice explicitly supplied in the conversation transcript. “New expansion” means fresh prose written for this website. Layout, illustrations, and navigation are editorial additions.','<span class="badge expansion">Source & provenance</span>')}</div><a class="textlink" href="#house">Read the editorial record ↗</a></section>`}
function doctrine(){return head('doctrine','The ways of the House','The Three Ho’s, the Great Ledger, and the practice of generosity: a coherent reading of the original teachings.')+`<div class="wrap">${original}<div class="three">${[['The First Ho','The world is saved by gifts freely given.'],['The Second Ho','Every person is both child and Santa.'],['The Third Ho','Joy is a duty, not a luxury.']].map(x=>`<div class="pillar"><h3>${x[0]}</h3><p>${x[1]}</p></div>`).join('')}</div><div class="two" style="margin-top:35px">${block('The Great Giver & companions','Santa Claus is the Great Giver. Mrs. Claus is the Keeper of Warmth, care and hospitality. The Elves are the Makers, spirits of craft and creativity. The Reindeer are the Guides of courage and endurance. The Auditor, a Krampus-like figure, embodies the stern mercy of consequence.')}${block('The Naughty & Nice Principle','Every action writes a mark in the Great Ledger. Adults, too, remain under revision. No soul is wholly Naughty or wholly Nice; generosity, honesty and repair move the heart toward Nice. Cruelty, selfishness and deceit move it toward Naughty.')}${block('Toyland & Lessons Unwrapped','Toyland is the afterlife of endless creativity, play and shared gifts. Hell is the Realm of Unwrapped Lessons: the soul confronts its harm and makes spiritual amends. It is not eternal; a softened heart may return to Toyland.')}${block('The Doctrine of Giftification','Every person has a talent, skill or virtue to discover, refine and give to the world. Hoarding a gift wastes its purpose; using it to harm others is a serious wrong.')}${block('The Law of Lists','Thought shapes reality in the fictional teaching. Wish Lists honour hope; Thank Lists cultivate gratitude. A balanced life maintains both asking and appreciating.')}${block('The Inner Child','Each person bears an Inner Child who can still hear the sleigh-bells. Protecting and listening to that child is a sacred duty. The companions may be understood as literal beings, metaphors, or both: “mythically real.”')}</div><h2>The List of Lights</h2>${original}<ol class="code-list">${CANON.code.map(x=>`<li>${x}</li>`).join('')}</ol><h2 style="margin-top:45px">The Creed of the House</h2>${original}${quote(CANON.creed)}<p class="note">Editorial concordance: the transcript calls joy both “not a luxury” and “not a toy.” Both original formulations are retained in their respective sources.</p></div>`}
function scripture(){return head('scripture','The sacred writings','The Book of Ho, Chapter the First, and A Psalm of the Sleigh-bells. Original archaic English, with verse numbering preserved.')+`<div class="wrap reader"><aside><a href="#scripture/book">Book of Ho · 1:1–32</a><a href="#scripture/psalm">Psalm of Ho · 1–9</a><a href="#scripture/children">For the little ones</a></aside><div><div class="note">Original wording is preserved; transcript line breaks, bold emphasis and quotation layout have been normalized for reading. Proposed titles—the Book of Lists, Naughty & Nice Ledger, and Gospel of Gifts—were named but not supplied as full books; no missing scripture is presented as recovered text.</div><div class="searchbar"><label><span class="sr-only">Search scripture</span><input id="scripture-search" type="search" placeholder="Search the writings… try ‘wonder’ or ‘gift’"></label><select id="book-filter" aria-label="Filter scripture"><option value="all">All writings</option><option value="book">Book of Ho</option><option value="psalm">Psalm of Ho</option></select></div><div id="verse-count" class="result-count" aria-live="polite"></div><div id="verses"></div><section id="children"><h2 class="book-title">The Night Horace Heard Ho Ho Ho</h2>${expansion}<p>The transcript preserves this children’s book’s title and plot, but not its prose. The following is a newly composed retelling of that outline.</p><div class="panel"><h3>A little story for a winter evening</h3><p>One snowy night, Horace heard three merry calls. “Ho! Ho! Ho!” He was grown up, but the child inside him was still listening.</p><p>“I am the Great Giver,” said the voice. “Share what you have. Remember that everyone needs help, and everyone can help. Keep joy alive.”</p><p>Then Horace saw a great book. Kind choices and hurtful choices were written on its pages. Nobody’s page was finished.</p><p>“What happens when we hurt someone?” Horace asked. “We learn to understand the hurt and make amends,” said the Giver. “Lessons Unwrapped is a place to learn, and Toyland is a place of shared gifts and play.”</p><p>So Horace opened the Holy House: a house of making, mending, laughter and giving. And whenever the bells rang, he remembered to listen.</p></div><h3>The children’s mini-creed</h3>${original}${quote(CANON.childCreed)}</section></div></div>`}
function highlight(s,q){if(!q)return esc(s);const safe=q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');return esc(s).replace(new RegExp(safe.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'),'gi'),m=>`<mark>${m}</mark>`)}
function updateVerses(){let q=$('#scripture-search').value.trim(),f=$('#book-filter').value,total=0;$('#verses').innerHTML=[['book','The Book of Ho, Chapter the First',CANON.verses],['psalm','A Psalm of the Sleigh-bells (Psalm of Ho)',CANON.psalm]].filter(x=>f==='all'||f===x[0]).map(([id,title,arr])=>{let found=arr.map((t,i)=>({t,i})).filter(x=>x.t.toLowerCase().includes(q.toLowerCase()));total+=found.length;return found.length?`<section id="${id}"><h2 class="book-title">${title}</h2>${original}${found.map(x=>`<div class="verse" id="${id}-${x.i+1}"><a class="verse-number" href="#scripture/${id}-${x.i+1}" aria-label="${id==='book'?'Book of Ho 1:':'Psalm of Ho '}${x.i+1}">${x.i+1}</a>${highlight(x.t,q)}</div>`).join('')}</section>`:''}).join('')||'<p class="empty-state">No verses found. Try another word or choose all writings.</p>';$('#verse-count').textContent=`${total} of 41 verses${q?' matching “'+q+'”':''}`}
function catechism(){return head('catechism','The HoHoHo Catechism','Twenty-one questions on the Great Giver, the Three Ho’s, and the life of a Clausbearer. Search by question, answer, or teaching.')+`<div class="wrap">${original}<div class="searchbar"><label><span class="sr-only">Search catechism</span><input id="catechism-search" type="search" placeholder="What wouldst thou know? Search the catechism…"></label><select id="topic-filter" aria-label="Filter catechism topic"><option value="all">All teachings</option>${[...new Set(CANON.catechism.map(x=>x[0]))].map(t=>`<option>${t}</option>`).join('')}</select></div><div class="toolbar"><button id="expand-all">Open all answers</button><button id="collapse-all">Close all answers</button></div><div id="qa-count" class="result-count" aria-live="polite"></div><div id="questions"></div></div>`}
function updateQA(){let q=$('#catechism-search').value.trim(),topic=$('#topic-filter').value;let found=CANON.catechism.map((x,i)=>({x,i})).filter(({x})=>(topic==='all'||x[0]===topic)&&x.join(' ').toLowerCase().includes(q.toLowerCase()));$('#questions').innerHTML=found.map(({x,i})=>`<details class="qa" ${q?'open':''} id="q${i+1}"><summary><span class="qnum">${String(i+1).padStart(2,'0')}</span><span><div class="qtopic">${x[0]}</div>${highlight(x[1],q)}</span></summary><div class="answer" style="white-space:pre-line">${highlight(x[2],q)}</div></details>`).join('')||'<p class="empty-state">No questions found. Try another word or choose all teachings.</p>';$('#qa-count').textContent=`${found.length} of 21 questions`}
function rites(){return head('rites','Rites & liturgy','From the quiet Morning List to the High Feast of Ho: the words and practices that give the House its rhythm.')+`<div class="wrap"><div class="two">${block('The Morning List','Take five minutes. Write one thing you are grateful for, one gift you will give today—time, help, a joke or support—and one secret wish to keep the Inner Child alive.')}${block('The Evening Stocking Check','Empty the stocking of the heart: What did I give? Did I slip anything harmful into another’s stocking through unkindness or neglect? Do I need to apologize or fix something?')}${block('The Workshop of Mirth','Gather weekly, online or in person, to make art, code, toys, food or solutions. Share or donate the work. Creation and generosity together are worship.')}${block('The Rite of Unwrapping','At a birthday, New Year or milestone, offer a symbolic empty box for limitless potential. The recipient chooses a gift name, such as “Bright Engineer Elf” or “Guardian of Games.”')}</div><h2>The Rite of Entry</h2><div class="note">The transcript supplies the ceremony’s elements and order, and the full oath below. Spoken lines in the rite below are new reconstructions, explicitly marked.</div>${original}<p>Prepare a candle or string of lights, a stocking, and a bell, ornament or token. Participants: the Grand Ho or a High Elf, a Reindeacon, and the candidate.</p><div class="liturgy">${[['The light & the reading','The Reindeacon lights the candle or lights. The leader reads the Three Ho’s from Book of Ho 1:14–16.'],['The Stocking Question','Leader: “Wilt thou open the stocking of thy heart, to receive with thanks and give without bargain?” Candidate: “I will.”'],['The Ledger acknowledged','Leader: “Dost thou acknowledge both Naughty and Nice within thee, and wilt thou mend the harm thou makest?” Candidate: “I do, and I will return to the path of giving.”'],['The oath','The candidate speaks the original Oath of the Clausbearer, printed below.'],['The token bestowed','The leader gives the bell or ornament: “Bear this token in remembrance of gift, joy, and wonder.”'],['The closing','All speak the short creed from Catechism Q21. The leader offers the original closing blessing below.']].map((x,i)=>`<div class="step"><span class="number">${i+1}.</span><h3>${x[0]}</h3>${[1,2,4].includes(i)?expansion:original}<p>${x[1]}</p></div>`).join('')}</div><h3>Oath of the Clausbearer</h3>${original}${quote(CANON.oath)}<details class="qa"><summary>A simple oath</summary><div class="answer">${expansion}<p>The transcript mentions a modern oath without supplying its wording. This version is newly composed.</p><p>I, [Name], promise to share my gifts, mend the harm I cause, welcome forgiveness, and protect wonder. I will give freely, make room for joy, and keep learning whenever I stray. Ho. Ho. Ho.</p></div></details><h2 style="margin-top:50px">The High Feast of Ho</h2><p>December 24–25 · An order for gathering around a tree or lights.</p><div class="note">All eight movements are attested in the transcript. The greeting, gift prayer, creed and final blessing are original; additional directions and the confession are new liturgical expansions.</div><div class="liturgy"><div class="step"><h3>I. Gathering & opening greeting</h3>${original}<p><span class="role">Leader</span> Ho, Ho, Hope be with you.<br><span class="role">All</span> And also with your gifts.</p></div><div class="step"><h3>II. Lighting of the lights / tree</h3>${expansion}<p>Light the tree or candles in silence, remembering the small kindnesses that illuminate a dark season.</p></div><div class="step"><h3>III. Reading from the Book of Ho</h3>${expansion}<p>Read Book of Ho 1:1–17, the calling of Horace and the Three Ho’s. Keep a moment of quiet.</p><a href="#scripture/book" class="textlink">Open the reading ↗</a></div><div class="step"><h3>IV. The Three Ho’s: call & response</h3>${expansion}<p><span class="role">Leader</span> What saveth the world?<br><span class="role">All</span> Gifts freely given.<br><span class="role">Leader</span> What beareth every soul?<br><span class="role">All</span> A child in need, and a Santa who giveth.<br><span class="role">Leader</span> What shall we kindle?<br><span class="role">All</span> Joy, our sacred duty.</p></div><div class="step"><h3>V. Confession & Stocking Check</h3>${expansion}${quote('Great Giver, we have hoarded what might have healed,\nand withheld the kindness we might have given.\nOpen our hearts to apology,\nand guide our hands to mend what we have broken.')}<p>Pause for the Evening Stocking Check; choose one act of repair.</p></div><div class="step"><h3>VI. Stories of generosity</h3>${expansion}<p>Invite stories of gifts freely given, without requiring anyone to speak or reveal a secret giver.</p></div><div class="step"><h3>VII. Secret gifts & blessing of gifts</h3>${expansion}<p>Place anonymous gifts together, to share or donate. Speak the original prayer:</p>${original}${quote(CANON.giftPrayer)}</div><div class="step"><h3>VIII. Closing creed & final blessing</h3>${expansion}<p>Speak the Creed of the House together, then receive the blessing:</p>${original}${quote(CANON.blessing)}<a href="#doctrine" class="textlink">Read the Creed ↗</a></div></div></div>`}
let calDate=new Date();function seasonFor(m){return [['Season of Spark','Beginnings, small kindnesses, and discovering your gifts.'],['Season of Growing Gifts','Practice, training, and refining talents and habits of kindness.'],['Season of Midyear Ho','Review, course-correction, and playful honesty.'],['Season of Wrapping','Preparation, secret plans, and generosity.']][Math.floor(m/3)]}
function calendar(){return head('calendar','The turning of the year','Four seasons of giving; one hearth kept warm. Original observances are distinguished from optional scheduling conventions.')+`<div class="wrap"><div class="season">${[0,3,6,9].map((m,i)=>`<div><span class="caption">${['JAN — MAR','APR — JUN','JUL — SEP','OCT — DEC'][i]}</span><h3>${seasonFor(m)[0]}</h3><p>${seasonFor(m)[1]}</p></div>`).join('')}</div><div id="season-note" class="note"></div><div class="calendar-controls"><button id="prev-month" aria-label="Previous month">←</button><h2 id="month-title"></h2><button id="next-month" aria-label="Next month">→</button><button id="today-month">Today</button></div><div class="calendar" id="calendar-grid" aria-label="Religious calendar"></div><p class="caption" style="margin-top:15px">Gold outline: today · Dates use your device’s local calendar</p><div class="two" style="margin-top:35px">${block('The High Feast of Ho','December 24–25. Secret giving, storytelling of legendary generosity, and lighting of the tree or candles.')}${block('The Midyear Check','July 25. Christmas in July: revisit gift goals, examine Naughty/Nice patterns, and set course corrections.')}${block('The Day of Unwrapping','Birthdays, New Year, or personal milestones. An empty box marks possibility; a chosen gift name marks a calling.')}${block('Monthly & weekly observances','Secret Santa Sabbaths and Workshop of Mirth Day are monthly observances. The weekly Workshop gathering remains a separate regular practice.')}</div>${expansion}<p class="note">Scheduling convention for this edition: Secret Santa Sabbath is placed on the first Sunday of each month; Workshop of Mirth Day on the third Saturday. The source specifies “monthly” but gives no weekday. January 1 is shown as one optional Day of Unwrapping; personal birthdays and milestones are not collected.</p><button class="btn" id="download-calendar">Download this year’s calendar (.ics)</button></div>`}
function monthlyEvents(y,m){const firstSunday=1+(7-new Date(y,m,1).getDay())%7,thirdSaturday=1+(6-new Date(y,m,1).getDay()+7)%7+14;let e=[{d:firstSunday,t:'Secret Santa Sabbath',new:true},{d:thirdSaturday,t:'Workshop of Mirth Day',new:true}];if(m===11)e.push({d:24,t:'High Feast of Ho'},{d:25,t:'High Feast of Ho'});if(m===6)e.push({d:25,t:'Midyear Check'});if(m===0)e.push({d:1,t:'Day of Unwrapping (optional)',new:true});return e}
function drawCalendar(){let y=calDate.getFullYear(),m=calDate.getMonth(),days=new Date(y,m+1,0).getDate(),start=new Date(y,m,1).getDay(),now=new Date(),e=monthlyEvents(y,m);$('#month-title').textContent=calDate.toLocaleDateString('en',{month:'long',year:'numeric'});$('#season-note').textContent=seasonFor(m).join(' — ');$('#calendar-grid').innerHTML=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(x=>`<div class="weekday">${x}</div>`).join('')+Array.from({length:start},()=>'<div class="day empty" aria-hidden="true"></div>').join('')+Array.from({length:days},(_,i)=>`<div class="day ${y===now.getFullYear()&&m===now.getMonth()&&i+1===now.getDate()?'today':''}" ${y===now.getFullYear()&&m===now.getMonth()&&i+1===now.getDate()?'aria-current="date"':''}><span>${i+1}</span>${e.filter(x=>x.d===i+1).map(x=>`<span class="event">${x.t}${x.new?' *':''}</span>`).join('')}</div>`).join('');$('#calendar-grid').setAttribute('aria-label',$('#month-title').textContent+' religious calendar');}
function download(name,text,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function calendarDownload(){let y=calDate.getFullYear(),rows=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//HoHoHo//Fictional Calendar//EN','CALSCALE:GREGORIAN'];for(let m=0;m<12;m++)for(const e of monthlyEvents(y,m)){let d=new Date(y,m,e.d),next=new Date(y,m,e.d+1),format=d=>`${d.getFullYear()}${String(d.getMonth()+1).padStart(2,'0')}${String(d.getDate()).padStart(2,'0')}`,date=format(d);rows.push('BEGIN:VEVENT',`UID:${date}-${e.t.replace(/\W/g,'').toLowerCase()}@hohoho.fiction`,`DTSTAMP:${new Date().toISOString().replace(/[-:]/g,'').split('.')[0]}Z`,`DTSTART;VALUE=DATE:${date}`,`DTEND;VALUE=DATE:${format(next)}`,`SUMMARY:${e.t}`,`DESCRIPTION:Fictional HoHoHo observance. ${e.new?'Date convention newly composed for this edition.':'Date preserved from the supplied transcript.'}`,'END:VEVENT')}rows.push('END:VCALENDAR');download(`hohoho-${y}.ics`,rows.join('\r\n')+'\r\n','text/calendar')}
function symbolArt(kind){const positions={stocking:[0,0],bells:[50,0],cane:[100,0],star:[0,100],ledger:[50,100]};const labels={stocking:"Left-facing crimson heart-stocking",bells:"Three golden sleigh bells",cane:"Crimson and ivory candy cane",star:"Eight-point golden winter star",ledger:"Open ivory and crimson Great Ledger"};const pos=positions[kind];return `<div class="sacred-symbol" role="img" aria-label="${labels[kind]}" style="background-position:${pos[0]}% ${pos[1]}%"></div>`}
function symbols(){return head('symbols','The signs of wonder','Stocking, bell, and winter light: the visual language of an ancient winter order of Santa.')+`<div class="wrap"><div class="note">A visual glossary of the House. These illustrations are newly created for this edition; the meanings below come from the original canon.</div><div class="symbols"><article class="symbol">${seal()}${original}<h3>The seal of the House</h3><p>The emblem of the House: a left-facing crimson stocking, three golden bells, evergreen branches and a winter star.</p></article>${[['stocking','The Heart-Stocking','The heart’s readiness to receive grace and give it. A hung stocking remains open to mercy.'],['bells','The Three Bells','The Three Ho’s made visible. The sleigh-bell is the sound only believers truly hear.'],['cane','The Candy Cane','Sweetness held in balance with discipline: kindness without abandoning consequence.'],['star','The Winter Star','Winter and wonder, a small light against the season’s darkness.'],['ledger','The Great Ledger','Naughty and Nice: choices under constant revision. No heart is wholly one or the other.']].map(x=>`<article class="symbol">${symbolArt(x[0])}${original}<h3>${x[1]}</h3><p>${x[2]}</p></article>`).join('')}</div><h2 style="margin-top:45px">The colours of the House</h2>${original}<div class="three">${[['#C62828','Red · Love'],['#0F3B2E','Green · Growth'],['#F9A825','Gold · Joy'],['#FDF8E4','Snow cream · Wonder'],['#222222','Charcoal night'],['#5D4037','Soft cocoa']].map(x=>`<div class="panel"><div style="height:45px;background:${x[0]};margin-bottom:16px"></div><h4>${x[1]}</h4><span class="caption">${x[0]}</span></div>`).join('')}</div><p class="note">The source associates white with wonder and also supplies Snow Cream as a palette colour. Candy Cane Mint (#A7FFEB) is its optional accent. This website uses subdued evergreen, deep red, parchment and antique gold for its ecclesiastical presentation.</p></div>`}
function house(){return head('house','The House & its keepers','A fellowship of hearts rather than walls. The original offices, the workshop community, and the editorial record of this fictional canon.')+`<div class="wrap"><div class="hierarchy">${original}${[['I','Grand Ho','Horace, founder and founding guide; the first Keeper of the Ho.'],['II','High Elves','Senior members, teachers and organizers.'],['III','Toysmiths','Those who create things for others.'],['IV','Reindeacons','Guides who tend community logistics, care and support.'],['V','Clausbearers','Regular members who carry the spirit of giving.']].map(x=>`<div class="rank"><span class="number">${x[0]}</span><div><h3>${x[1]}</h3><p>${x[2]}</p></div></div>`).join('')}<p class="note">Editorial note: this order follows the source’s list of titles. The transcript does not establish authority of Toysmiths over Reindeacons; these are parallel forms of service, not additional invented ranks.</p><h2 style="margin-top:45px">A sacred workshop</h2><p>The House may gather in person or online. Its sacred space is a workshop of making and mending, where craft becomes generosity and labour becomes an offering. A bell or ornament may be worn as a sign.</p><h2>The editorial record</h2><p>This website organizes one supplied conversation into a reference canon. “Original” refers to material present in that transcript, including its earlier assistant-generated fiction; it is not a claim of historical antiquity.</p><div class="panel"><h3>What survives in full</h3><p>The 32-verse Book of Ho, the nine-verse Psalm, all 21 catechism answers, the eight Ho-mandments, the long and short creeds, the Clausbearer’s oath, formal credential text, children’s mini-creed, gift prayer, greeting and closing blessing.</p></div><div class="panel"><h3>What survives as an outline</h3><p>The initiation rite, eight-part High Feast liturgy, modern oath, playful membership card, and children’s story were summarized in the transcript. Their newly written prose is marked as expansion. No omitted booklet or generated image has been treated as an available attachment.</p></div><div class="panel"><h3>What this edition adds</h3><p>Nine-section organization, responsive navigation, search and filters, illustrated symbols, a browsable calendar with disclosed monthly date conventions, and a printable fictional membership certificate. No new scripture has been inserted into the original Book or Psalm.</p></div><p class="note">This is satire and imaginative worldbuilding, not a claim of supernatural authority, a registered religious institution, or a legally recognized credential.</p></div></div>`}
function membership(){return head('membership','Become a Clausbearer','A symbolic credential for a fictional fellowship. Make a certificate, speak the oath, and keep the Ho in your heart.')+`<div class="wrap"><div class="note">This is a fictional souvenir, not registration with a real religious institution. Your entries remain in this page’s memory and are not submitted or stored. The browser’s Print dialog can save a PDF.</div><div class="membership"><form class="fields" id="certificate-form"><h3>Prepare thy credential</h3><label>Name<input id="member-name" placeholder="Your name" maxlength="70" autocomplete="off"></label><label>Gift name (optional)<input id="gift-name" placeholder="e.g. Guardian of Games" maxlength="70" autocomplete="off"></label><label>Date of entry<input id="entry-date" type="date"></label><label>Year of Ho<input id="ho-year" placeholder="Leave blank if unspecified" maxlength="15"></label><label>Grand Ho<input id="grand-ho" placeholder="Horace" maxlength="50"></label><label>High Elf (witness)<input id="witness" placeholder="Witness name or signature" maxlength="50"></label><button class="btn" type="submit">Print / save certificate</button><p style="font-size:12px;color:var(--muted);margin-top:14px">Original formal credential wording. Layout, optional gift-name field and fiction notice are additions.</p></form><section class="certificate" id="certificate" aria-label="Membership certificate preview"><div class="seal-small">${seal()}</div><span class="eyebrow" style="margin:15px 0">Holy House of Horace (HoHoHo)</span><h2>Clausbearer’s Credential</h2><p>This certifieth that</p><div class="certificate-name" id="cert-name">____________________</div><p id="cert-gift" hidden></p><p>is numbered among the <strong>Clausbearers</strong> of the<br><strong>Holy House of Horace</strong>,<br>having taken the Oath of the Ho<br>and pledged to keep the ways of<br><em>gift, joy, and wonder</em><br>under the merry gaze of the <strong>Great Giver</strong>.</p><p>Given this day of <span id="cert-date"></span>,<br>in the Year of Ho <span id="cert-year">________</span>.</p><div class="signatures"><span>Grand Ho: <span id="cert-grand">________________</span></span><span>High Elf (Witness): <span id="cert-witness">________________</span></span></div><hr style="border:0;border-top:1px solid var(--gold)"><h3 style="margin:22px 0 12px">The Three Ho’s</h3><p>1. The world is saved by <strong>gifts freely given</strong>.<br>2. Each soul is both <strong>child and Santa</strong>.<br>3. <strong>Joy is a duty</strong>, not a toy.</p><p><em>“He that keepeth the Ho keepeth the Hearth.”</em></p><small>FICTIONAL · SATIRICAL WORLDBUILDING · NO LEGAL OR RELIGIOUS STATUS</small></section></div><h2 style="margin-top:60px">The promise before the token</h2>${original}${quote(CANON.oath)}<a class="textlink" href="#rites">Read the complete Rite of Entry ↗</a><details class="qa" style="margin-top:30px"><summary>A playful companion card</summary><div class="answer">${expansion}<p>The source mentions a playful card but supplies no text. This is a new companion version:</p><p><strong>Certified Clausbearer</strong><br>Keeper of gifts. Mender of mishaps. Defender of the Inner Child.<br>Membership rule: Give freely. No strings. Batteries of kindness included.<br>Ho. Ho. Ho.</p></div></details></div>`}
function syncCertificate(){let val=id=>$('#'+id).value.trim();$('#cert-name').textContent=val('member-name')||'____________________';$('#cert-gift').textContent=val('gift-name');$('#cert-gift').hidden=!val('gift-name');let date=val('entry-date');$('#cert-date').textContent=date?new Date(date+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'}):'____________';$('#cert-year').textContent=val('ho-year')||'________';$('#cert-grand').textContent=val('grand-ho')||'________________';$('#cert-witness').textContent=val('witness')||'________________'}
let lastSection='';function render(){let [id,target]=location.hash.slice(1).split('/');if(!sections.some(x=>x[0]===id))id='welcome';if(id===lastSection&&target){document.getElementById(target)?.scrollIntoView();return}lastSection=id;$('#content').innerHTML=({welcome,doctrine,scripture,catechism,rites,calendar,symbols,house,membership}[id])();$('#content').classList.remove('reveal');void $('#content').offsetWidth;$('#content').classList.add('reveal');document.title=`${sections.find(x=>x[0]===id)[1]} · Holy House of Horace`;document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.hash==='#'+id);if(a.hash==='#'+id)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('#nav').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');if(id==='scripture'){$('#scripture-search').addEventListener('input',updateVerses);$('#book-filter').addEventListener('change',updateVerses);updateVerses()}if(id==='catechism'){$('#catechism-search').addEventListener('input',updateQA);$('#topic-filter').addEventListener('change',updateQA);$('#expand-all').onclick=()=>document.querySelectorAll('.qa').forEach(d=>d.open=true);$('#collapse-all').onclick=()=>document.querySelectorAll('.qa').forEach(d=>d.open=false);updateQA()}if(id==='calendar'){drawCalendar();$('#prev-month').onclick=()=>{calDate=new Date(calDate.getFullYear(),calDate.getMonth()-1,1);drawCalendar()};$('#next-month').onclick=()=>{calDate=new Date(calDate.getFullYear(),calDate.getMonth()+1,1);drawCalendar()};$('#today-month').onclick=()=>{calDate=new Date();drawCalendar()};$('#download-calendar').onclick=calendarDownload}if(id==='membership'){let d=new Date();$('#entry-date').value=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;$('#certificate-form').addEventListener('input',syncCertificate);$('#certificate-form').onsubmit=e=>{e.preventDefault();window.print()};syncCertificate()}window.scrollTo(0,0);if(target)requestAnimationFrame(()=>document.getElementById(target)?.scrollIntoView());}
$('#nav').innerHTML=sections.map(([id,label])=>`<a href="#${id}">${label}</a>`).join('');$('#menu').onclick=()=>{let open=$('#nav').classList.toggle('open');$('#menu').setAttribute('aria-expanded',String(open))};window.addEventListener('hashchange',render);render();

document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();document.getElementById('content').focus();});
